#include <stdio.h>
#include <stdlib.h>

#define MAX_TASKS 100

typedef struct { void (*run)(void*); void *arg; } Task;

typedef struct { Task tasks[MAX_TASKS]; int front, rear, count; } TaskQueue;

void tq_init(TaskQueue *q) { q->front = q->rear = q->count = 0; }
void tq_enqueue(TaskQueue *q, Task t) {
    if (q->count < MAX_TASKS) {
        q->tasks[q->rear] = t;
        q->rear = (q->rear + 1) % MAX_TASKS;
        q->count++;
    }
}
Task tq_dequeue(TaskQueue *q) {
    Task t = q->tasks[q->front];
    q->front = (q->front + 1) % MAX_TASKS;
    q->count--;
    return t;
}

void print_task(void *arg) { printf("Task: %s\n", (char*)arg); }
void add_task(void *arg) { int *vals = (int*)arg; printf("Sum: %d\n", vals[0] + vals[1]); }

int main() {
    TaskQueue q;
    tq_init(&q);
    tq_enqueue(&q, (Task){print_task, "Hello"});
    int vals[2] = {10, 20};
    tq_enqueue(&q, (Task){add_task, vals});
    tq_enqueue(&q, (Task){print_task, "World"});
    while (q.count > 0) {
        Task t = tq_dequeue(&q);
        t.run(t.arg);
    }
    return 0;
}
